#include "epub.h"
#include <ctype.h>
#include <stdlib.h>
#include <string.h>
enum {F_FONT=1,F_ALIGN=2,F_INDENT=4,F_TOP=8,F_BOTTOM=16,F_LEFT=32,F_RIGHT=64,F_HEIGHT=128,F_FLAGS=256,F_COLOR=512,F_IW=1024,F_IH=2048};
static char*trim(char*p){while(isspace((unsigned char)*p))p++;char*z=p+strlen(p);while(z>p&&isspace((unsigned char)z[-1]))*--z=0;return p;}
static int number(const char*s,int font){int sign=1;if(*s=='-'){sign=-1;s++;}int n=0,fraction=0,unit=100;while(isdigit((unsigned char)*s)){if(n>10000)return 0;n=n*10+*s++-'0';}if(*s=='.'){s++;while(isdigit((unsigned char)*s)){if(unit){fraction+=(*s-'0')*unit;unit/=10;}s++;}}n=n*1000+fraction;if(!strncmp(s,"px",2)||!strncmp(s,"pt",2))n=n/16;else if(*s=='%')n/=100;else if(!strncmp(s,"rem",3)){}else if(*s&&!strncmp(s,"em",2)){}else if(font&&!*s)n=n;return sign*n;}
static uint16_t color(const char*s){unsigned n=0;if(s[0]=='#'){s++;unsigned len=(unsigned)strspn(s,"0123456789abcdefABCDEF");if(len!=3&&len!=6)return 0;for(unsigned i=0;i<len;i++){unsigned c=(unsigned char)s[i];n=n*16+(c<='9'?c-'0':(c|32)-'a'+10);}if(len==3)n=((n&0xf00)<<12)|((n&0xf00)<<8)|((n&0xf0)<<8)|((n&0xf0)<<4)|((n&15)<<4)|(n&15);return (uint16_t)(((n>>19)&31)<<11|((n>>10)&63)<<5|((n>>3)&31));}if(!strcasecmp(s,"red"))return 0xf800;if(!strcasecmp(s,"blue"))return 0x001f;if(!strcasecmp(s,"white"))return 0xffff;if(!strcasecmp(s,"gray"))return 0x8410;return 0;}
void ep_inline_props(struct ep_props*p,const char*input){char text[4096];if(strlen(input)>=sizeof text)return;strcpy(text,input);char*cursor=text;while(*cursor){char*end=strchr(cursor,';');if(end)*end=0;char*colon=strchr(cursor,':');if(colon){*colon=0;char*k=trim(cursor),*v=trim(colon+1);char*important=strstr(v,"!important");if(important)*important=0;struct ep_style*s=&p->value;
 if(!strcasecmp(k,"font-size")){s->font=number(v,1);p->font_relative=strstr(v,"em")&&!strstr(v,"rem")||strchr(v,'%');p->mask|=F_FONT;}
 else if(!strcasecmp(k,"font-weight")){if(!strcasecmp(v,"bold")||atoi(v)>=600)s->flags|=EP_BOLD;else s->flags&=~EP_BOLD;p->mask|=F_FLAGS;}
 else if(!strcasecmp(k,"font-family")){if(strstr(v,"SimHei")||strstr(v,"黑体")){s->flags|=EP_BOLD;p->mask|=F_FLAGS;}}
 else if(!strcasecmp(k,"font-style")){if(!strcasecmp(v,"italic")||!strcasecmp(v,"oblique"))s->flags|=EP_ITALIC;p->mask|=F_FLAGS;}
 else if(!strcasecmp(k,"text-decoration")){if(strstr(v,"underline"))s->flags|=EP_UNDERLINE;p->mask|=F_FLAGS;}
 else if(!strcasecmp(k,"vertical-align")){if(!strcasecmp(v,"super"))s->flags|=EP_SUP;else if(!strcasecmp(v,"sub"))s->flags|=EP_SUB;p->mask|=F_FLAGS;}
 else if(!strcasecmp(k,"white-space")){if(!strncasecmp(v,"pre",3))s->flags|=EP_PRE;p->mask|=F_FLAGS;}
 else if(!strcasecmp(k,"display")&&!strcasecmp(v,"none")){s->flags|=EP_HIDDEN;p->mask|=F_FLAGS;}
 else if(!strcasecmp(k,"page-break-before")||!strcasecmp(k,"break-before")){if(!strcasecmp(v,"always")||!strcasecmp(v,"page"))s->flags|=EP_BREAK_BEFORE;p->mask|=F_FLAGS;}
 else if(!strcasecmp(k,"text-align")){s->align=!strcasecmp(v,"center")?1:!strcasecmp(v,"right")?2:!strcasecmp(v,"justify")?3:0;p->mask|=F_ALIGN;}
 else if(!strcasecmp(k,"text-indent")){s->indent=number(v,0);p->mask|=F_INDENT;}
 else if(!strcasecmp(k,"line-height")){s->height=number(v,0);if(s->height<=0)s->height=1400;p->mask|=F_HEIGHT;}
 else if(!strcasecmp(k,"margin-top")){s->top=number(v,0);p->mask|=F_TOP;}
 else if(!strcasecmp(k,"margin-bottom")){s->bottom=number(v,0);p->mask|=F_BOTTOM;}
 else if(!strcasecmp(k,"margin-left")||!strcasecmp(k,"padding-left")){s->left=number(v,0);p->mask|=F_LEFT;}
 else if(!strcasecmp(k,"margin-right")||!strcasecmp(k,"padding-right")){s->right=number(v,0);p->mask|=F_RIGHT;}
 else if(!strcasecmp(k,"margin")){int vals[4]={0};unsigned n=0;char*scan=v;while(*scan&&n<4){while(isspace((unsigned char)*scan))scan++;vals[n++]=number(scan,0);while(*scan&&!isspace((unsigned char)*scan))scan++;}if(n){s->top=vals[0];s->bottom=n>2?vals[2]:vals[0];s->left=n>3?vals[3]:n>1?vals[1]:vals[0];s->right=n>1?vals[1]:vals[0];p->mask|=F_TOP|F_BOTTOM|F_LEFT|F_RIGHT;}}
 else if(!strcasecmp(k,"color")){s->color=color(v);s->colored=1;p->mask|=F_COLOR;}
 else if(!strcasecmp(k,"width")||!strcasecmp(k,"height")){int n=number(v,0);/* positive = em units; negative = fixed design pixels */if(strstr(v,"px")||!strstr(v,"em")){n=atoi(v);if(n>0)n=-n;}if(!strcasecmp(k,"width")){s->imgw=n;p->mask|=F_IW;}else{s->imgh=n;p->mask|=F_IH;}}
 }if(!end)break;cursor=end+1;}}
static void apply(struct ep_style*s,const struct ep_props*p,int inherited_font){const struct ep_style*v=&p->value;unsigned m=p->mask;if(m&F_FONT){s->font=p->font_relative?inherited_font*v->font/1000:v->font;if(s->font<400)s->font=400;if(s->font>4000)s->font=4000;}if(m&F_ALIGN)s->align=v->align;if(m&F_INDENT)s->indent=v->indent;if(m&F_TOP)s->top=v->top;if(m&F_BOTTOM)s->bottom=v->bottom;if(m&F_LEFT)s->left=v->left;if(m&F_RIGHT)s->right=v->right;if(m&F_HEIGHT)s->height=v->height;if(m&F_FLAGS)s->flags|=v->flags;if(m&F_COLOR){s->color=v->color;s->colored=v->colored;}if(m&F_IW)s->imgw=v->imgw;if(m&F_IH)s->imgh=v->imgh;}
void ep_css(struct ep_book*b,const char*input,unsigned length){if(length>524288)return;char*text=malloc(length+1);if(!text)return;unsigned n=0;for(unsigned i=0;i<length;i++){if(i+1<length&&input[i]=='/'&&input[i+1]=='*'){i+=2;while(i+1<length&&(input[i]!='*'||input[i+1]!='/'))i++;i++;}else text[n++]=input[i];}text[n]=0;char*p=text;while(*p){char*open=strchr(p,'{');if(!open)break;char*end=strchr(open+1,'}');if(!end)break;*open=0;*end=0;char*selectors=trim(p);if(selectors[0]!='@'){struct ep_props props={0};ep_inline_props(&props,open+1);char*at=selectors;while(*at&&b->rule_count<256){char*comma=strchr(at,',');if(comma)*comma=0;char*sel=trim(at);if(*sel&&strlen(sel)<128){struct ep_rule*r=b->rules+b->rule_count++;strcpy(r->selector,sel);r->props=props;for(char*q=sel;*q;q++)r->specificity+=*q=='#'?100:*q=='.'?10:0;r->specificity+=sel[0]!='.'&&sel[0]!='#';}if(!comma)break;at=comma+1;}}p=end+1;}free(text);}
static int word(const char*classes,const char*target){unsigned n=(unsigned)strlen(target);const char*p=classes;while(*p){while(isspace((unsigned char)*p))p++;const char*z=p;while(*z&&!isspace((unsigned char)*z))z++;if((unsigned)(z-p)==n&&!memcmp(p,target,n))return 1;p=z;}return 0;}
static int matches(const char*selector,const char*tag,const char*classes,const char*id){if(strchr(selector,' ')||strchr(selector,'>')||strchr(selector,'[')||strchr(selector,':'))return 0;char copy[128];strcpy(copy,selector);char*p=copy,*q=p;while(*q&&*q!='.'&&*q!='#')q++;char saved=*q;*q=0;if(*p&&strcmp(p,"*")&&strcasecmp(p,tag))return 0;*q=saved;p=q;while(*p){char kind=*p++;q=p;while(*q&&*q!='.'&&*q!='#')q++;saved=*q;*q=0;int ok=kind=='.'?word(classes,p):kind=='#'?!strcmp(id,p):0;*q=saved;if(!ok)return 0;p=q;}return 1;}
struct ep_style ep_style_for(struct ep_book*b,const struct ex_tag*t,const struct ep_style*parent){struct ep_style s=*parent;s.top=s.bottom=s.left=s.right=0;s.imgw=s.imgh=0;s.flags&=~EP_BREAK_BEFORE;char classes[512],id[128],inline_css[2048];ex_attribute(t,"class",classes,sizeof classes);ex_attribute(t,"id",id,sizeof id);const char*tag=strrchr(t->name,':');tag=tag?tag+1:t->name;
 if(!strcasecmp(tag,"p")){s.top=s.bottom=500;}else if(tag[0]=='h'&&tag[1]>='1'&&tag[1]<='6'&&!tag[2]){s.font=parent->font*(tag[1]=='1'?1800:tag[1]=='2'?1500:1250)/1000;s.flags|=EP_BOLD;s.top=1000;s.bottom=600;}else if(!strcasecmp(tag,"blockquote")){s.left=s.right=1000;s.top=s.bottom=500;}else if(!strcasecmp(tag,"b")||!strcasecmp(tag,"strong"))s.flags|=EP_BOLD;else if(!strcasecmp(tag,"i")||!strcasecmp(tag,"em"))s.flags|=EP_ITALIC;else if(!strcasecmp(tag,"u"))s.flags|=EP_UNDERLINE;else if(!strcasecmp(tag,"sup"))s.flags|=EP_SUP;else if(!strcasecmp(tag,"sub"))s.flags|=EP_SUB;else if(!strcasecmp(tag,"pre"))s.flags|=EP_PRE;
 /* Apply matching simple selectors in ascending specificity, preserving source order. */
 unsigned seen[256]={0};for(unsigned j=0;j<b->rule_count;j++){unsigned best=256;for(unsigned i=0;i<b->rule_count;i++)if(!seen[i]&&matches(b->rules[i].selector,tag,classes,id)&&(best==256||b->rules[i].specificity<b->rules[best].specificity))best=i;if(best==256)break;seen[best]=1;apply(&s,&b->rules[best].props,parent->font);}
 if(ex_attribute(t,"style",inline_css,sizeof inline_css)){struct ep_props p={0};ep_inline_props(&p,inline_css);apply(&s,&p,parent->font);}char attr[64];if(ex_attribute(t,"align",attr,sizeof attr))s.align=!strcasecmp(attr,"center")?1:!strcasecmp(attr,"right")?2:0;if(ex_attribute(t,"width",attr,sizeof attr)&&atoi(attr)>0)s.imgw=-atoi(attr);if(ex_attribute(t,"height",attr,sizeof attr)&&atoi(attr)>0)s.imgh=-atoi(attr);return s;}
